/* @lc app=leetcode id=3910 lang=kotlin */ class Solution { fun evenSumSubgraphs(nums: IntArray, edges: Array<IntArray>): Int = nums.size.let { n -> IntArray(n).also { adj -> edges.forEach { (a, b) -> adj[a] = adj[a] or (1 shl b) }.also { edges.forEach { (a, b) -> adj[b] = adj[b] or (1 shl a) } } }.let { adj -> (1 until (1 shl n)).count { m -> (0 until n).filter { m shr it and 1 == 1 }.sumOf { nums[it] } % 2 == 0 && (0 until n).fold(m and -m) { r, _ -> (r or (0 until n).filter { r shr it and 1 == 1 }.fold(0) { a, i -> a or adj[i] }) and m } == m } } } }